import java.awt.*;
import java.awt.image.BufferedImage;

final class EnvironmentView {
    static final String[] BIOMES={"plains","plains","ocean","river","snowy_plains","swamp","desert","forest","frozen_ocean","frozen_river","meadow","grove","snowy_slopes","jagged_peaks","stony_peaks","taiga"};
    static final Color[] BIOME_COLORS={new Color(93,152,78),new Color(93,152,78),new Color(25,85,155),new Color(53,159,210),new Color(220,236,240),new Color(76,107,73),new Color(219,190,114),new Color(36,105,62),new Color(142,201,225),new Color(172,222,237),new Color(131,181,90),new Color(70,110,88),new Color(232,240,244),new Color(214,224,232),new Color(140,138,132),new Color(50,95,70)};
    static int biome(TerraForge.World w,int x,int z){int i=z*w.size+x;if(w.environment.biome!=null&&w.environment.biome[i]>0)return w.environment.biome[i];if(w.waterY(x,z)>w.h(x,z))return w.iceDepth(x,z)>0?8:2;if(w.snowLayers(x,z)>2||TerrainGenerator.surface(w,x,z)==4)return 4;return TerrainGenerator.surface(w,x,z)==2?6:1;}
    static Color material(int m){return switch(m){case 2->new Color(213,196,139);case 3->new Color(128,133,137);case 4->new Color(225,233,234);case 5->new Color(103,92,72);case 6,9->new Color(148,203,225);case 7->new Color(147,140,130);case 8->new Color(129,95,66);case 10->new Color(125,103,74);case 11->new Color(118,122,119);case 12->new Color(140,141,139);case 14->new Color(106,78,45);case 15->new Color(139,103,75);case 16->new Color(91,119,53);case 17->new Color(183,182,176);case 18->new Color(149,113,96);case 19->new Color(108,109,102);case 20->new Color(223,224,219);case 13->new Color(101,120,83);default->new Color(88,145,76);};}
    static Color gradient(float f,Color a,Color b){double t=TerrainGenerator.clamp(f,0,1);return new Color((int)(a.getRed()*(1-t)+b.getRed()*t),(int)(a.getGreen()*(1-t)+b.getGreen()*t),(int)(a.getBlue()*(1-t)+b.getBlue()*t));}
    static Color surfaceColor(TerraForge.World w,int x,int z){int i=z*w.size+x;Color ground=material(TerrainGenerator.surface(w,x,z));float snow=EnvironmentMap.at(w.environment.snow,i,0);return gradient(snow,ground,new Color(230,238,240));}
    static int riverSample(TerraForge.World w,int px,int pz,int display){
        int x0=px*w.size/display,z0=pz*w.size/display,best=z0*w.size+x0;float strength=0;
        if(w.environment.river==null)return best;
        for(int z=z0;z<(pz+1)*w.size/display;z++)for(int x=x0;x<(px+1)*w.size/display;x++){int i=z*w.size+x;float r=w.environment.river[i];if(r>strength&&w.environment.waterY(i,w.sea)>Math.round(w.height[i])){best=i;strength=r;}}
        return best;
    }
    static BufferedImage render(TerraForge.World w,int layer){int n=w.size,display=Math.min(n,2048);BufferedImage out=new BufferedImage(display,display,BufferedImage.TYPE_INT_RGB);for(int pz=0;pz<display;pz++)for(int px=0;px<display;px++){int x=px*n/display,z=pz*n/display;if(n>display&&(layer==0||layer==1||layer==6)){int sample=riverSample(w,px,pz,display);x=sample%n;z=sample/n;}int i=z*n+x,h=w.h(x,z),water=w.waterY(x,z),depth=Math.max(0,water-h);Color c;
        switch(layer){case 1->c=depth>0?gradient(depth/60f,new Color(65,198,216),new Color(12,35,92)):new Color(48,59,66);case 2->c=gradient(w.environment.snow==null?(TerrainGenerator.surface(w,x,z)==4?1:0):w.environment.snow[i],new Color(38,55,62),Color.WHITE);case 3->c=gradient(Math.max(EnvironmentMap.at(w.environment.ice,i,0)/5,EnvironmentMap.at(w.environment.glacier,i,0)/30),new Color(38,55,62),new Color(146,226,252));case 4->c=gradient(EnvironmentMap.at(w.environment.temperature,i,.5f),new Color(80,136,230),new Color(241,117,66));case 5->c=gradient(EnvironmentMap.at(w.environment.rain,i,.5f),new Color(192,154,101),new Color(36,153,171));case 6->c=BIOME_COLORS[biome(w,x,z)];default->{if(depth>0)c=w.iceDepth(x,z)>0?new Color(165,215,237):new Color(24,Math.max(45,112-depth),156);else c=surfaceColor(w,x,z);}}
        if(layer==0&&x>0&&z>0){double shade=TerrainGenerator.clamp(1+(w.visibleY(x-1,z)-w.visibleY(x,z))*.045+(w.visibleY(x,z-1)-w.visibleY(x,z))*.025,.5,1.35);c=new Color((int)Math.min(255,c.getRed()*shade),(int)Math.min(255,c.getGreen()*shade),(int)Math.min(255,c.getBlue()*shade));}out.setRGB(px,pz,c.getRGB());}if(layer==0&&!w.environment.trees.isEmpty()){if(n<=2048)w.treeHeights=TreeLibrary.canopy(w,out);else{Graphics2D g=out.createGraphics();g.setColor(new Color(36,81,44));for(var p:w.environment.trees){int r=Math.max(1,TreeLibrary.catalog().trees().get(p.tree()).width*display/n/2);g.fillOval(p.x()*display/n-r,p.z()*display/n-r,r*2,r*2);}g.dispose();}}return out;}
}
